{"command": "cat > /workspace/src/hostsfile.go <<'EOF'
package main

import (
	"bufio"
	"net"
	"os"
	"strings"
)

// Entry is one line of "unmanaged" (default) content of a hosts file.
type Entry struct {
	Kind  int // 0 = blank, 1 = comment / verbatim text, 2 = host row
	IP    net.IP
	Host  string
	Text  string // verbatim/comment text
}

const (
	entryBlank = iota
	entryText
	entryHost
)

// IPGroup holds all host names attached to a single IP inside a profile.
type IPGroup struct {
	IP    net.IP
	Hosts []string
}

// Profile is a named group of hosts inside the hostctl managed block.
type Profile struct {
	Name   string
	Status bool // true == on
	IPs    []IPGroup
}

// HostsFile is the parsed representation of a hosts file.
type HostsFile struct {
	Path     string
	Default  []Entry
	names    []string
	profiles map[string]*Profile
}

func newHostsFile(path string) *HostsFile {
	return &HostsFile{Path: path, profiles: map[string]*Profile{}}
}

// Names returns the ordered list of profile names found in the file.
// The list may contain duplicates when a profile header repeats.
func (h *HostsFile) Names() []string { return h.names }

// Profile looks a profile up by name.
func (h *HostsFile) Profile(name string) (*Profile, bool) {
	p, ok := h.profiles[name]
	return p, ok
}

// HasProfile reports whether a profile with the given name exists.
func (h *HostsFile) HasProfile(name string) bool {
	_, ok := h.profiles[name]
	return ok
}

// AddProfile creates a brand new profile (replacing any existing one with the
// same name) and records its position at the end of the file.
func (h *HostsFile) AddProfile(name string, status bool) *Profile {
	p := &Profile{Name: name, Status: status}
	h.profiles[name] = p
	h.names = append(h.names, name)
	return p
}

// RemoveProfile drops every occurrence of a profile from the file.
func (h *HostsFile) RemoveProfile(name string) {
	delete(h.profiles, name)
	out := h.names[:0]
	for _, n := range h.names {
		if n != name {
			out = append(out, n)
		}
	}
	h.names = out
}

// uniqueNames returns the profile names without duplicates, in file order.
func (h *HostsFile) uniqueNames() []string {
	seen := map[string]bool{}
	var out []string
	for _, n := range h.names {
		if !seen[n] {
			seen[n] = true
			out = append(out, n)
		}
	}
	return out
}

// AddIP appends a host name to the (existing or new) group of the given IP.
func (p *Profile) AddIP(ip net.IP, host string) {
	for i := range p.IPs {
		if p.IPs[i].IP.String() == ip.String() {
			p.IPs[i].Hosts = append(p.IPs[i].Hosts, host)
			return
		}
	}
	p.IPs = append(p.IPs, IPGroup{IP: ip, Hosts: []string{host}})
}

// RemoveHosts removes every host name matching one of the given names.
func (p *Profile) RemoveHosts(domains []string) {
	var groups []IPGroup
	for _, g := range p.IPs {
		var hosts []string
		for _, h := range g.Hosts {
			dropped := false
			for _, d := range domains {
				if d == h {
					dropped = true
					break
				}
			}
			if !dropped {
				hosts = append(hosts, h)
			}
		}
		if len(hosts) > 0 {
			groups = append(groups, IPGroup{IP: g.IP, Hosts: hosts})
		}
	}
	p.IPs = groups
}

// Rows returns every (ip, host) pair of the profile, grouped by IP.
func (p *Profile) Rows() [][2]string {
	var rows [][2]string
	for _, g := range p.IPs {
		for _, h := range g.Hosts {
			rows = append(rows, [2]string{g.IP.String(), h})
		}
	}
	return rows
}

var (
	profileRe = regexpProfile()
	endMarker = "# end"
)

// lineProfileRe matches the hostctl profile header:
//   # profile[.on|.off] <name>
// The name may only contain lower case letters, digits, "_", "-" and "."
// followed by any amount of white space characters.
func regexpProfile() *regExpr { return compileProfile() }

// Parse reads and interprets a hosts file.
func Parse(path string) (*HostsFile, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	hs := newHostsFile(path)
	var cur *Profile
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		trim := strings.TrimSpace(line)

		if strings.HasPrefix(strings.ToLower(trim), endMarker) {
			cur = nil
			continue
		}

		if name, status, ok := matchProfileHeader(trim); ok {
			cur = hs.AddProfile(name, status)
			continue
		}

		if cur != nil {
			body := trim
			if strings.HasPrefix(body, "#") {
				body = strings.TrimSpace(body[1:])
			}
			if i := strings.Index(body, "#"); i >= 0 {
				body = body[:i]
			}
			fields := strings.Fields(body)
			if len(fields) < 2 {
				continue
			}
			ip := net.ParseIP(fields[0])
			if ip == nil {
				continue
			}
			for _, h := range fields[1:] {
				cur.AddIP(ip, h)
			}
			continue
		}

		switch {
		case trim == "":
			hs.Default = append(hs.Default, Entry{Kind: entryBlank})
		case strings.HasPrefix(trim, "#"):
			hs.Default = append(hs.Default, Entry{Kind: entryText, Text: trim})
		default:
			fields := strings.Fields(trim)
			ip := net.ParseIP(fields[0])
			if ip == nil {
				hs.Default = append(hs.Default, Entry{Kind: entryText, Text: trim})
				continue
			}
			host := ""
			if len(fields) > 1 {
				host = cutComment(fields[1])
			}
			if host == "" {
				hs.Default = append(hs.Default, Entry{Kind: entryText, Text: trim})
				continue
			}
			hs.Default = append(hs.Default, Entry{Kind: entryHost, IP: ip, Host: host})
		}
	}
	return hs, nil
}

func cutComment(s string) string {
	if i := strings.Index(s, "#"); i >= 0 {
		s = s[:i]
	}
	return s
}
EOF
