		switch e.Kind {
		case entryHost:
			if e.Host == "" {
				line = e.IP.String()
			} else {
				line = e.IP.String() + " " + e.Host
			}
		case entryText:
			line = e.Text
		}
		if line == "" {
			if lastBlank {
				continue
			}
			b.WriteString("\n")
			lastBlank = true
			continue
		}
		b.WriteString(line)
		b.WriteString("\n")
		lastBlank = false
	}

	if !lastBlank {
		b.WriteString("\n")
	}
	b.WriteString(headerLine + "\n" + contentNotice + "\n" + headerLine + "\n")

	for _, name := range h.names {
