func matchProfileHeader(trim string) (name string, status bool, ok bool) {
	m := profileRe.FindStringSubmatch(trim)
	if m == nil {
		return "", false, false
	}
	name = strings.TrimSpace(m[3])
	status = m[2] != ".off"
	return name, status, true
}

// Parse reads a hosts file and builds its in memory representation.
func Parse(path string) (*HostsFile, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	hs := newHostsFile(path)
	var cur *Profile
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
	for sc.Scan() {
		trim := strings.TrimSpace(sc.Text())

		if strings.HasPrefix(strings.ToLower(trim), "# end") {
			cur = nil
			continue
		}

		if name, status, ok := matchProfileHeader(trim); ok {
			cur = hs.AddProfile(name, status)
			continue
		}

		if cur != nil {
			body := trim
			if strings.HasPrefix(body, "#") {
				body = strings.TrimSpace(body[1:])
			}
			if i := strings.Index(body, "#"); i >= 0 {
				body = body[:i]
			}
			fields := strings.Fields(body)
			if len(fields) < 2 {
				continue
			}
			ip := net.ParseIP(fields[0])
			if ip == nil {
				continue
			}
			for _, h := range fields[1:] {
				cur.AddIP(ip, h)
			}
			continue
		}

		switch {
		case trim == "":
			hs.Default = append(hs.Default, Entry{Kind: entryBlank})
		case strings.HasPrefix(trim, "#"):
			hs.Default = append(hs.Default, Entry{Kind: entryText, Text: trim})
		default:
			fields := strings.Fields(trim)
			ip := net.ParseIP(fields[0])
			if ip == nil {
				hs.Default = append(hs.Default, Entry{Kind: entryText, Text: trim})
				continue
			}
			host := ""
			if len(fields) > 1 {
				host = cutComment(fields[1])
			}
			if host == "" {
				hs.Default = append(hs.Default, Entry{Kind: entryText, Text: trim})
				continue
			}
			hs.Default = append(hs.Default, Entry{Kind: entryHost, IP: ip, Host: host})
		}
	}
	return hs, nil
}

func cutComment(s string) string {
	if i := strings.Index(s, "#"); i >= 0 {
		s = s[:i]
	}
	return s
}

