	headerLine      = "##################################################################"
	contentNotice   = "# Content under this line is handled by hostctl. DO NOT EDIT."
	defaultBlockTop = "\n" + headerLine + "\n" + contentNotice + "\n" + headerLine + "\n"
)

// String renders the hosts file content, ready to be written back to disk.
func (h *HostsFile) String() string {
	var b strings.Builder
	lastBlank := false
	for _, e := range h.Default {
		var line string
		switch e.Kind {
		case entryHost:
			if e.Host == "" {
				line = e.IP.String()
			} else {
				line = e.IP.String() + " " + e.Host
			}
		case entryText:
			line = e.Text
		}
		if line == "" {
			if lastBlank {
				continue
			}
			b.WriteString("\n")
			lastBlank = true
			continue
		}
		b.WriteString(line)
		b.WriteString("\n")
		lastBlank = false
	}

	if !lastBlank {
		b.WriteString("\n")
	}
	b.WriteString(headerLine + "\n" + contentNotice + "\n" + headerLine + "\n")

	for _, name := range h.names {
		p := h.profiles[name]
		if p == nil {
			continue
		}
		b.WriteString("\n")
		status := "on"
		if !p.Status {
			status = "off"
		}
		b.WriteString("# profile." + status + " " + p.Name + "\n")
		for _, g := range p.IPs {
			for _, host := range g.Hosts {
				line := g.IP.String() + " " + host
				if !p.Status {
					line = "# " + line
				}
				b.WriteString(line + "\n")
			}
		}
		b.WriteString("# end\n")
	}
	return b.String()
}

// Save writes the hosts file back to disk.
func (h *HostsFile) Save() error {
	return os.WriteFile(h.Path, []byte(h.String()), 0644)
}
