package main

import (
	"fmt"
	"strings"
)

// Row is one line of the report produced by the list/status commands.
type Row struct {
	Profile string
	Status  string
	IP      string
	Host    string
}

// Column is a single column of the report.
type Column struct {
	Name  string
	Title string
}

// defaultColumns is the column set used by the list command.
func defaultColumns() []Column {
	return columnsFromNames([]string{"profile", "status", "ip", "domain"})
}

// statusColumns is the fixed column set used by the status command.
func statusColumns() []Column {
	return columnsFromNames([]string{"profile", "status"})
}

func columnsFromNames(names []string) []Column {
	out := make([]Column, 0, len(names))
	for _, n := range names {
		out = append(out, Column{Name: n, Title: strings.ToUpper(n)})
	}
	return out
}

// value returns the content of a column for a row. Unknown column names yield
// an empty string (they still get a column, but without data).
func (c Column) value(r Row) string {
	switch c.Name {
	case "profile":
		return r.Profile
	case "status":
		return r.Status
	case "ip":
		return r.IP
	case "domain":
		return r.Host
	}
	return ""
}

// grid is the layout of a report: a header line plus groups of data rows.
type grid struct {
	columns []Column
	header  []string
	groups  [][]string
}

// buildGrid converts rows into the tab separated grid used by all renderers.
// Empty data cells are dropped, exactly like the original tool does.
func buildGrid(columns []Column, groups [][]Row) *grid {
	g := &grid{columns: columns, header: make([]string, len(columns))}
	for i, c := range columns {
		g.header[i] = c.Title
	}
	g.groups = make([][]string, 0, len(groups))
	for _, grp := range groups {
		cells := make([]string, 0, len(columns))
		for _, r := range grp {
			for _, c := range columns {
				if v := c.value(r); v != "" {
					cells = append(cells, v)
				}
			}
		}
		if len(cells) == 0 {
			continue
		}
		g.groups = append(g.groups, cells)
	}
	return g
}

// widths computes the width of every column of the grid.
func (g *grid) widths() []int {
	w := make([]int, 0, len(g.header))
	for _, h := range g.header {
		w = append(w, len(h))
	}
	grow := func(cells []string) {
		for len(w) < len(cells) {
			w = append(w, 0)
		}
		for i, c := range cells {
			if len(c) > w[i] {
				w[i] = len(c)
			}
		}
	}
	grow(g.header)
	for _, grp := range g.groups {
		grow(grp)
	}
	return w
}

func (g *grid) empty() bool { return len(g.groups) == 0 }

func padRight(s string, w int) string {
	if len(s) >= w {
		return s
	}
	return s + strings.Repeat(" ", w-len(s))
}

func center(s string, w int) string {
	if len(s) >= w {
		return s
	}
	left := (w - len(s)) / 2
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", w-len(s)-left)
}

// RenderTable draws the bordered table representation of a report.
func RenderTable(columns []Column, groups [][]Row) string {
	g := buildGrid(columns, groups)
	if g.empty() {
		return ""
	}
	w := g.widths()

	var b strings.Builder
	border := func() {
		b.WriteString("+")
		for _, x := range w {
			b.WriteString(strings.Repeat("-", x+2))
			b.WriteString("+")
		}
		b.WriteString("\n")
	}
	border()
	b.WriteString(rowLine(g.header, w, true))
	border()
	for _, grp := range g.groups {
		b.WriteString(rowLine(grp, w, false))
		border()
	}
	return b.String()
}

func rowLine(cells []string, w []int, header bool) string {
	var b strings.Builder
	for i, c := range cells {
		var width int
		if i < len(w) {
			width = w[i]
		}
		if header {
			b.WriteString("| " + center(c, width) + " ")
		} else {
			b.WriteString("| " + padRight(c, width) + " ")
		}
	}
	b.WriteString("|")
	b.WriteString("\n")
	return b.String()
}

// RenderMarkdown draws the markdown representation of a report.
func RenderMarkdown(columns []Column, groups [][]Row) string {
	g := buildGrid(columns, groups)
	if g.empty() {
		return ""
	}
	w := g.widths()

	var b strings.Builder
	separator := func() {
		b.WriteString("|")
		for _, x := range w {
			b.WriteString(strings.Repeat("-", x+2))
			b.WriteString("|")
		}
		b.WriteString("\n")
	}
	b.WriteString(rowLine(g.header, w, true))
	separator()
	for _, grp := range g.groups {
		b.WriteString(rowLine(grp, w, false))
		separator()
	}
	return b.String()
}

// RenderRaw draws the border-less (tab separated) representation.
func RenderRaw(columns []Column, groups [][]Row) string {
	g := buildGrid(columns, groups)
	if g.empty() {
		return ""
	}
	w := g.widths()

	var b strings.Builder
	// header: every cell padded to the column width, the last one gets one
	// extra space.
	for i, c := range g.header {
		if i > 0 {
			b.WriteString("\t")
		}
		if i == len(g.header)-1 {
			b.WriteString(padRight(c, w[i]+1))
		} else {
			b.WriteString(padRight(c, w[i]))
		}
	}
	b.WriteString("\n")
	for _, grp := range g.groups {
		for i, c := range grp {
			if i > 0 {
				b.WriteString("\t")
			}
			if i < len(w) {
				b.WriteString(padRight(c, w[i]))
			} else {
				b.WriteString(c)
			}
		}
		b.WriteString("\t\n")
	}
	return b.String()
}

// RenderJSON renders the report as a JSON array of rows.
func RenderJSON(groups [][]Row) string {
	var rows []Row
	for _, grp := range groups {
		rows = append(rows, grp...)
	}
	data, err := jsonMarshal(rows)
	if err != nil {
		return ""
	}
	return data + "\n"
}

func jsonMarshal(v interface{}) (string, error) {
	return jsonEncode(v)
}

