	"strings"
)

// Row is one line of the report produced by the list/status commands.
type Row struct {
	Profile string
	Status  string
	IP      string
	Host    string
}

// Column is a single column of the report.
type Column struct {
	Name  string
	Title string
}

// defaultColumns is the column set used by the list command.
func defaultColumns() []Column {
	return columnsFromNames([]string{"profile", "status", "ip", "domain"})
}

// statusColumns is the fixed column set used by the status command.
func statusColumns() []Column {
	return columnsFromNames([]string{"profile", "status"})
}

func columnsFromNames(names []string) []Column {
	out := make([]Column, 0, len(names))
	for _, n := range names {
		out = append(out, Column{Name: n, Title: strings.ToUpper(n)})
	}
	return out
}

// value returns the content of a column for a row. Unknown column names yield
// an empty string (they still get a column, but without data).
func (c Column) value(r Row) string {
	switch c.Name {
	case "profile":
		return r.Profile
	case "status":
		return r.Status
	case "ip":
		return r.IP
	case "domain":
		return r.Host
	}
	return ""
}

// grid is the layout of a report: a header line plus groups of data rows.
type grid struct {
	columns []Column
	header  []string
	groups  [][]string
}

// buildGrid converts rows into the tab separated grid used by all renderers.
// Empty data cells are dropped, exactly like the original tool does.
func buildGrid(columns []Column, groups [][]Row) *grid {
	g := &grid{columns: columns, header: make([]string, len(columns))}
	for i, c := range columns {
		g.header[i] = c.Title
	}
	g.groups = make([][]string, 0, len(groups))
	for _, grp := range groups {
		cells := make([]string, 0, len(columns))
		for _, r := range grp {
			for _, c := range columns {
				if v := c.value(r); v != "" {
					cells = append(cells, v)
				}
			}
		}
		if len(cells) == 0 {
			continue
		}
		g.groups = append(g.groups, cells)
	}
	return g
}

// widths computes the width of every column of the grid.
func (g *grid) widths() []int {
	w := make([]int, 0, len(g.header))
	for _, h := range g.header {
		w = append(w, len(h))
	}
	grow := func(cells []string) {
		for len(w) < len(cells) {
			w = append(w, 0)
		}
		for i, c := range cells {
			if len(c) > w[i] {
				w[i] = len(c)
			}
		}
	}
	grow(g.header)
	for _, grp := range g.groups {
		grow(grp)
	}
	return w
}

func (g *grid) empty() bool { return len(g.groups) == 0 }

func padRight(s string, w int) string {
	if len(s) >= w {
		return s
	}
	return s + strings.Repeat(" ", w-len(s))
}

func center(s string, w int) string {
	if len(s) >= w {
		return s
	}
	left := (w - len(s)) / 2
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", w-len(s)-left)
}

