{"command": "cat > /workspace/src/cli.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

// Flag describes a single command line flag.
type Flag struct {
	Name     string
	Short    string
	Usage    string
	Kind     string // string | strings | bool | duration
	Str      string
	Strs     []string
	Bool     bool
	Dur      time.Duration
	NoOptDef string
	Changed  bool
	hidden   bool
}

// kind returns the pflag type name shown in the help output.
func (f *Flag) varName() string {
	switch f.Kind {
	case "string":
		return "string"
	case "strings":
		return "strings"
	case "duration":
		return "duration"
	}
	return ""
}

func (f *Flag) defaultIsZero() bool {
	switch f.Kind {
	case "string":
		return f.Str == ""
	case "strings":
		return len(f.Strs) == 0
	case "bool":
		return !f.Bool
	case "duration":
		return f.Dur == 0
	}
	return true
}

func (f *Flag) defString() string {
	switch f.Kind {
	case "string":
		return strconv.Quote(f.Str)
	case "strings":
		if len(f.Strs) == 0 {
			return "[]"
		}
		return "[" + strings.Join(f.Strs, ",") + "]"
	case "bool":
		return strconv.FormatBool(f.Bool)
	case "duration":
		return f.Dur.String()
	}
	return ""
}

func (f *Flag) set(value string) error {
	switch f.Kind {
	case "string":
		f.Str = value
	case "strings":
		v := strings.Split(value, ",")
		if !f.Changed {
			f.Strs = v
		} else {
			f.Strs = append(f.Strs, v...)
		}
	case "bool":
		b, err := strconv.ParseBool(value)
		if err != nil {
			return fmt.Errorf("strconv.ParseBool: parsing %q: invalid syntax", value)
		}
		f.Bool = b
	case "duration":
		d, err := time.ParseDuration(value)
		if err != nil {
			return err
		}
		f.Dur = d
	}
	f.Changed = true
	return nil
}

func (f *Flag) display() string {
	if f.Short != "" {
		return fmt.Sprintf("  -%s, --%s", f.Short, f.Name)
	}
	return fmt.Sprintf("      --%s", f.Name)
}

func (f *Flag) helpLine(maxlen int) string {
	line := f.display()
	if v := f.varName(); v != "" {
		line += " " + v
	}
	if !f.defaultIsZero() {
		if f.Kind == "string" {
			line += fmt.Sprintf(" (default %q)", f.Str)
		} else {
			line += fmt.Sprintf(" (default %s)", f.defString())
		}
	}
	spacing := strings.Repeat(" ", maxlen-len(line)+3)
	return line + spacing + f.Usage
}

// FlagSet holds the flags of a command (and its inherited ones).
type FlagSet struct {
	flags  []*Flag
	byName map[string]*Flag
	short  map[byte]*Flag
}

func newFlagSet() *FlagSet {
	return &FlagSet{byName: map[string]*Flag{}, short: map[byte]*Flag{}}
}

func (fs *FlagSet) add(f *Flag) {
	fs.flags = append(fs.flags, f)
	fs.byName[f.Name] = f
	if f.Short != "" {
		fs.short[f.Short[0]] = f
	}
}

func (fs *FlagSet) lookup(name string) *Flag { return fs.byName[name] }

func (fs *FlagSet) sorted() []*Flag {
	out := make([]*Flag, len(fs.flags))
	copy(out, fs.flags)
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j].Name < out[j-1].Name; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

// FlagUsages renders the flag help block the same way pflag does.
func (fs *FlagSet) FlagUsages() string {
	flags := fs.sorted()
	maxlen := 0
	for _, f := range flags {
		if f.hidden {
			continue
		}
		line := f.display()
		if v := f.varName(); v != "" {
			line += " " + v
		}
		if len(line)+1 > maxlen {
			maxlen = len(line) + 1
		}
	}
	var b strings.Builder
	for _, f := range flags {
		if f.hidden {
			continue
		}
		b.WriteString(f.helpLine(maxlen))
		b.WriteString("\n")
	}
	return b.String()
}

func hasNoOptDefVal(name string, fs *FlagSet) bool {
	f := fs.lookup(name)
	return f != nil && f.NoOptDef != ""
}

func shortHasNoOptDefVal(name string, fs *FlagSet) bool {
	if len(name) == 0 {
		return false
	}
	f := fs.short[name[0]]
	return f != nil && f.NoOptDef != ""
}

// parse parses the flags out of args and returns the positional arguments.
func (fs *FlagSet) parse(args []string) ([]string, error) {
	var positional []string
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		if len(s) == 0 || s[0] != '-' || len(s) == 1 {
			positional = append(positional, s)
			continue
		}
		if s[1] == '-' {
			if len(s) == 2 {
				positional = append(positional, args...)
				break
			}
			var err error
			args, err = fs.parseLong(s, args)
			if err != nil {
				return nil, err
			}
			continue
		}
		var err error
		args, err = fs.parseShort(s, args)
		if err != nil {
			return nil, err
		}
	}
	return positional, nil
}

func (fs *FlagSet) parseLong(s string, args []string) ([]string, error) {
	name := s[2:]
	if len(name) == 0 || name[0] == '-' || name[0] == '=' {
		return nil, fmt.Errorf("bad flag syntax: %s", s)
	}
	var value string
	var hasValue bool
	if i := strings.Index(name, "="); i >= 0 {
		value = name[i+1:]
		name = name[:i]
		hasValue = true
	}
	f := fs.lookup(name)
	if f == nil {
		return nil, fmt.Errorf("unknown flag: --%s", name)
	}
	switch {
	case hasValue:
	case f.NoOptDef != "":
		value = f.NoOptDef
	case len(args) > 0:
		value = args[0]
		args = args[1:]
	default:
		return nil, fmt.Errorf("flag needs an argument: %s", s)
	}
	if err := setFlagErr(f, value); err != nil {
		return nil, err
	}
	return args, nil
}

func (fs *FlagSet) parseShort(s string, args []string) ([]string, error) {
	shorthands := s[1:]
	var err error
	for len(shorthands) > 0 {
		shorthands, args, err = fs.parseSingleShort(shorthands, args)
		if err != nil {
			return nil, err
		}
	}
	return args, nil
}

func (fs *FlagSet) parseSingleShort(shorthands string, args []string) (string, []string, error) {
	c := shorthands[0]
	f := fs.short[c]
	if f == nil {
		return "", nil, fmt.Errorf("unknown shorthand flag: %q in -%s", string(c), shorthands)
	}
	outShorts := shorthands[1:]
	var value string
	switch {
	case len(shorthands) > 2 && shorthands[1] == '=':
		value = shorthands[2:]
		outShorts = ""
	case f.NoOptDef != "":
		value = f.NoOptDef
	case len(shorthands) > 1:
		value = shorthands[1:]
		outShorts = ""
	case len(args) > 0:
		value = args[0]
		args = args[1:]
	default:
		return "", nil, fmt.Errorf("flag needs an argument: %q in -%s", string(c), shorthands)
	}
	if err := setFlagErr(f, value); err != nil {
		return "", nil, err
	}
	return outShorts, args, nil
}

func setFlagErr(f *Flag, value string) error {
	if err := f.set(value); err != nil {
		var flagName string
		if f.Short != "" {
			flagName = fmt.Sprintf("-%s, --%s", f.Short, f.Name)
		} else {
			flagName = fmt.Sprintf("--%s", f.Name)
		}
		return fmt.Errorf("invalid argument %q for %q flag: %v", value, flagName, err)
	}
	return nil
}
