package main

import (
	"fmt"
	"os"
	"strings"
)

// Command mirrors the subset of cobra's behaviour that this tool relies on.
type Command struct {
	Use      string
	Aliases  []string
	Short    string
	Long     string
	Args     func(c *Command, args []string) error
	Run      func(c *Command, args []string) error
	PreRun   func(c *Command, args []string) error
	local    *FlagSet
	persist  *FlagSet
	parent   *Command
	children []*Command
	// runtime state
	fs *FlagSet // the merged flag set used for parsing
}

func newCmd(use, short, long string) *Command {
	return &Command{
		Use: use, Short: short, Long: long,
		local:   newFlagSet(),
		persist: newFlagSet(),
	}
}

// Name is the first word of Use.
func (c *Command) Name() string {
	name := c.Use
	if i := strings.Index(name, " "); i >= 0 {
		name = name[:i]
	}
	return name
}

// CommandPath is the space separated chain of command names.
func (c *Command) CommandPath() string {
	if c.parent == nil {
		return c.Name()
	}
	return c.parent.CommandPath() + " " + c.Name()
}

func (c *Command) addCommand(sub *Command) {
	sub.parent = c
	c.children = append(c.children, sub)
}

// flags returns the flag set used to parse the command line for this command:
// its own flags plus every persistent flag of its ancestors.
func (c *Command) flags() *FlagSet {
	if c.fs != nil {
		return c.fs
	}
	fs := newFlagSet()
	for _, f := range c.local.flags {
		fs.add(f)
	}
	// inherited persistent flags
	inherited := newFlagSet()
	for p := c.parent; p != nil; p = p.parent {
		for _, f := range p.persist.flags {
			if inherited.lookup(f.Name) == nil {
				inherited.add(f)
			}
		}
	}
	for _, f := range inherited.flags {
		fs.add(f)
	}
	c.fs = fs
	return fs
}

// LocalFlags are the flags shown in the "Flags:" help section.
func (c *Command) LocalFlags() *FlagSet { return c.local }

// InheritedFlags are the flags shown in the "Global Flags:" help section.
func (c *Command) InheritedFlags() *FlagSet {
	fs := newFlagSet()
	for p := c.parent; p != nil; p = p.parent {
		for _, f := range p.persist.flags {
			if fs.lookup(f.Name) == nil {
				fs.add(f)
			}
		}
	}
	return fs
}

func (c *Command) hasSubCommands() bool { return len(c.children) > 0 }

func (c *Command) findNext(name string) *Command {
	for _, sub := range c.children {
		if sub.Name() == name {
			return sub
		}
		for _, a := range sub.Aliases {
			if a == name {
				return sub
			}
		}
	}
	return nil
}

func (c *Command) hasAlias(name string) bool {
	for _, a := range c.Aliases {
		if a == name {
			return true
		}
	}
	return false
}

func (c *Command) nameAndAliases() string {
	parts := append([]string{c.Name()}, c.Aliases...)
	return strings.Join(parts, ", ")
}

func (c *Command) useLine() string {
	line := c.Use
	if c.parent != nil {
		line = c.parent.CommandPath() + " " + c.Use
	}
	if c.hasAvailableFlags() && !strings.Contains(line, "[flags]") {
		line += " [flags]"
	}
	return line
}

func (c *Command) hasAvailableFlags() bool {
	return len(c.local.flags) > 0 || len(c.InheritedFlags().flags) > 0
}

// namePadding mirrors cobra's rpad width for the command list.
func (c *Command) namePadding() int {
	const minNamePadding = 11
	max := minNamePadding
	if c.parent != nil {
		for _, sub := range c.parent.children {
			if len(sub.Name()) > max {
				max = len(sub.Name())
			}
		}
	}
	return max
}

func rpad(s string, padding int) string {
	if len(s) >= padding {
		return s
	}
	return s + strings.Repeat(" ", padding-len(s))
}

// usageString renders cobra's usage template.
func (c *Command) usageString() string {
	var b strings.Builder
	b.WriteString("Usage:")
	if c.Run != nil {
		b.WriteString("\n  " + c.useLine())
	}
	if c.hasSubCommands() {
		b.WriteString("\n  " + c.CommandPath() + " [command]")
	}
	if len(c.Aliases) > 0 {
		b.WriteString("\n\nAliases:\n  " + c.nameAndAliases())
	}
	if c.hasSubCommands() {
		b.WriteString("\n\nAvailable Commands:")
		pad := c.namePadding()
		for _, sub := range c.children {
			b.WriteString("\n  " + rpad(sub.Name(), pad) + " " + sub.Short)
		}
	}
	if lf := c.LocalFlags(); len(lf.flags) > 0 {
		b.WriteString("\n\nFlags:\n" + strings.TrimRight(lf.FlagUsages(), " \t\n"))
	}
	if inf := c.InheritedFlags(); len(inf.flags) > 0 {
		b.WriteString("\n\nGlobal Flags:\n" + strings.TrimRight(inf.FlagUsages(), " \t\n"))
	}
	if c.hasSubCommands() {
		b.WriteString("\n\nUse \"" + c.CommandPath() + " [command] --help\" for more information about a command.")
	}
	b.WriteString("\n")
	return b.String()
}

// helpString renders cobra's help template.
func (c *Command) helpString() string {
	var b strings.Builder
	long := c.Long
	if long == "" {
		long = c.Short
	}
	if long != "" {
		b.WriteString(strings.TrimRight(long, " \t\n") + "\n\n")
	}
	if c.Run != nil || c.hasSubCommands() {
		b.WriteString(c.usageString())
	}
	return b.String()
}

func (c *Command) printHelp() {
	out(c.helpString())
}

// stripFlags removes flags and their values, leaving the positional words.
func stripFlags(args []string, c *Command) []string {
	if len(args) == 0 {
		return args
	}
	fs := c.flags()
	commands := []string{}
Loop:
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		switch {
		case s == "--":
			break Loop
		case strings.HasPrefix(s, "--") && !strings.Contains(s, "=") && !hasNoOptDefVal(s[2:], fs):
			fallthrough
		case strings.HasPrefix(s, "-") && !strings.Contains(s, "=") && len(s) == 2 && !shortHasNoOptDefVal(s[1:], fs):
			if len(args) <= 1 {
				break Loop
			}
			args = args[1:]
			continue
		case s != "" && !strings.HasPrefix(s, "-"):
			commands = append(commands, s)
		}
	}
	return commands
}

func argsMinusFirstX(args []string, x string) []string {
	for i, y := range args {
		if x == y {
			out := []string{}
			out = append(out, args[:i]...)
			out = append(out, args[i+1:]...)
			return out
		}
	}
	return args
}

// find walks the command tree following the given arguments.
func (c *Command) find(args []string) (*Command, []string, error) {
	var inner func(*Command, []string) (*Command, []string)
	inner = func(cc *Command, innerArgs []string) (*Command, []string) {
		woFlags := stripFlags(innerArgs, cc)
		if len(woFlags) == 0 {
			return cc, innerArgs
		}
		next := woFlags[0]
		if sub := cc.findNext(next); sub != nil {
			return inner(sub, argsMinusFirstX(innerArgs, next))
		}
		return cc, innerArgs
	}
	found, a := inner(c, args)
	if found.Args == nil {
		return found, a, legacyArgs(found, stripFlags(a, found))
	}
	return found, a, nil
}

func legacyArgs(c *Command, args []string) error {
	if !c.hasSubCommands() {
		return nil
	}
	if c.parent == nil && len(args) > 0 {
		return fmt.Errorf("unknown command %q for %q", args[0], c.CommandPath())
	}
	return nil
}

var errHelpRequested = fmt.Errorf("help requested")

// execute parses and runs the command line, returning the resolved command.
func (c *Command) execute(args []string) (*Command, error) {
	target, targetArgs, err := c.find(args)
	if err != nil {
		return c, err
	}
	fs := target.flags()
	positional, err := fs.parse(targetArgs)
	if err != nil {
		return target, err
	}

	if h := fs.lookup("help"); h != nil && h.Bool {
		return target, errHelpRequested
	}
	if v := fs.lookup("version"); v != nil && v.Bool && target.parent == nil {
		out("hostctl version " + version + "\n")
		return target, nil
	}

	if target.Args != nil {
		if err := target.Args(target, positional); err != nil {
			return target, err
		}
	}
	if target.Run == nil {
		target.printHelp()
		return target, nil
	}
	if target.PreRun != nil {
		if err := target.PreRun(target, positional); err != nil {
			return target, err
		}
	}
	if err := target.Run(target, positional); err != nil {
		return target, err
	}
	return target, nil
}

func out(s string) { os.Stdout.WriteString(s) }
EOF
