		if name == "default" {
			for _, e := range hs.Default {
				if e.Kind != entryHost {
					continue
				}
				rows = append(rows, Row{Profile: "default", Status: "on", IP: e.IP.String(), Host: e.Host})
			}
			groups = append(groups, rows)
			continue
		}
		p, ok := hs.Profile(name)
		if !ok {
			continue
		}
		status := "on"
		if !p.Status {
			status = "off"
		}
		for _, g := range p.IPs {
			if g.IP == nil {
				continue
			}
			for _, h := range g.Hosts {
