		s := RenderTable(columns, groups)
		if newline {
			out(s + "\n")
		} else {
			out(s)
		}
	}
}

func outputType(c *Command) string {
	o := "table"
	if f := c.flags().lookup("out"); f != nil {
		o = f.Str
	}
	if f := c.flags().lookup("raw"); f != nil && f.Bool {
		return "raw"
	}
	return o
}

func columnsFor(c *Command) []Column {
	if f := c.flags().lookup("column"); f != nil && len(f.Strs) > 0 {
		return columnsFromNames(f.Strs)
	}
	return defaultColumns()
}
