package main

import (
	"errors"
	"fmt"
	"net"
	"os"
	"path/filepath"
	"strings"
	"time"
)

func (c *Command) hostsFilePath() string {
	f := c.flags().lookup("host-file")
	if f != nil && f.Str != "" {
		return f.Str
	}
	return defaultHostsFile
}

func (c *Command) hs() *HostsFile {
	if c.parent != nil && c.parent.hsFile != nil {
		return c.parent.hsFile
	}
	return c.hsFile
}

var errDefaultProfile = errors.New("'default' profile should not be handled by hostctl")
var errMissingProfile = errors.New("missing profile name")
var errUnknownProfile = errors.New("unknown profile name")

func checkProfileArgs(args []string) error {
	for _, a := range args {
		if a == "default" {
			return errDefaultProfile
		}
	}
	return nil
}

func contains(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}

func allProfileNames(hs *HostsFile) []string {
	return append([]string{"default"}, hs.UniqueNames()...)
}

func affectedNames(hs *HostsFile, args []string) []string {
	if len(args) > 0 {
		return args
	}
	return allProfileNames(hs)
}

func filterStatus(hs *HostsFile, names []string, want string) []string {
	var out []string
	for _, n := range names {
		if n == "default" {
			out = append(out, n)
			continue
		}
		p, ok := hs.Profile(n)
		if !ok {
			continue
		}
		s := "on"
		if !p.Status {
			s = "off"
		}
		if want == "" || s == want {
			out = append(out, n)
		}
	}
	return out
}

// ---------------------------------------------------------------- pre-run

func hostsPreRun(c *Command, args []string) error {
	path := c.hostsFilePath()
	if !quiet(c) && path != defaultHostsFile {
		infoMsg(c, "Using hosts file: "+path)
	}
	hs, err := Parse(path)
	if err != nil {
		return err
	}
	c.hsFile = hs
	return nil
}

// ---------------------------------------------------------------- list

func runList(want string) func(*Command, []string) error {
	return func(c *Command, args []string) error {
		hs := c.hs()
		names := affectedNames(hs, args)
		if want != "" {
			names = filterStatus(hs, names, want)
