	if err != nil {
		return err
	}
	c.hsFile = hs
	return nil
}

// ------------------------------------------------------------------ list

func runList(want string) func(*Command, []string) error {
	return func(c *Command, args []string) error {
		hs := c.hosts()
		names := affectedNames(hs, args)
		if want != "" {
			names = filterStatus(hs, names, want)
		}
		printList(c, renderGroups(hs, names))
		return nil
	}
}

func runStatus(want string) func(*Command, []string) error {
	return func(c *Command, args []string) error {
		hs := c.hosts()
		names := affectedNames(hs, args)
		var rows []Row
		for _, n := range names {
			if n == "default" {
				continue
			}
			p, ok := hs.Profile(n)
			if !ok {
				continue
			}
			s := "on"
			if !p.Status {
				s = "off"
			}
			if want == "" || s == want {
				rows = append(rows, Row{Profile: p.Name, Status: s})
			}
		}
		var groups [][]Row
		if len(rows) > 0 {
			groups = append(groups, rows)
		}
		printList(c, groups)
		return nil
	}
}

// ------------------------------------------------------------------ enable/disable

func setStatus(hs *HostsFile, args []string, target bool, all, only bool) ([]string, error) {
	names := hs.UniqueNames()
	switch {
	case only:
		for _, n := range names {
			hs.profiles[n].Status = contains(args, n) == target
		}
	case all:
		for _, n := range names {
			hs.profiles[n].Status = target
		}
	default:
		for _, a := range args {
			p, ok := hs.Profile(a)
			if !ok {
				return nil, errUnknownProfile
			}
			p.Status = target
		}
	}
	if all {
		return allProfileNames(hs), nil
	}
	return args, nil
}

func saveHosts(hs *HostsFile) error { return hs.Save() }

func doEnable(c *Command, args []string, target bool, all, only bool) error {
	hs := c.hosts()
	affected, err := setStatus(hs, args, target, all, only)
	if err != nil {
		return err
	}
	if err := saveHosts(hs); err != nil {
		return err
	}
	printResult(c, renderGroups(hs, affected))
	return nil
}

func doToggle(c *Command, args []string) error {
	hs := c.hosts()
	for _, a := range args {
		p, ok := hs.Profile(a)
		if !ok {
			return errUnknownProfile
		}
		p.Status = !p.Status
	}
	if err := saveHosts(hs); err != nil {
		return err
	}
	printResult(c, renderGroups(hs, args))
	return nil
}

// doDisableLike is the reverse action of the wait flow: it prints the report
// without the trailing blank line used by the commands themselves.
func reverseEnable(c *Command, args []string, target bool) error {
	hs := c.hosts()
	affected, err := setStatus(hs, args, target, false, false)
	if err != nil {
		return err
	}
	if err := saveHosts(hs); err != nil {
		return err
	}
	printQuiet(c, renderGroups(hs, affected))
	return nil
}

func reverseToggle(c *Command, args []string) error {
	hs := c.hosts()
	for _, a := range args {
		p, ok := hs.Profile(a)
		if !ok {
			return errUnknownProfile
		}
		p.Status = !p.Status
	}
	if err := saveHosts(hs); err != nil {
		return err
	}
	printQuiet(c, renderGroups(hs, args))
	return nil
}

// ------------------------------------------------------------------ remove

func doRemove(c *Command, args []string) error {
	hs := c.hosts()
	var names []string
	if all := flagBool(c, "all"); all {
		names = hs.UniqueNames()
		if len(names) == 0 {
			return errNoProfiles
		}
	} else {
		for _, a := range args {
			if !hs.HasProfile(a) {
				return errUnknownProfile
			}
		}
		names = args
	}
	for _, n := range names {
		hs.RemoveProfile(n)
	}
	if err := saveHosts(hs); err != nil {
		return err
	}
	okMsg(c, fmt.Sprintf("Profile(s) '%s' removed.", strings.Join(names, ", ")))
	printResult(c, renderGroups(hs, names))
	return nil
}

// doRemoveDomains removes the given domains from a single profile.
func doRemoveDomains(c *Command, args []string) error {
	hs := c.hosts()
	profile := args[0]
	domains := args[1:]
	p, ok := hs.Profile(profile)
	if !ok {
		return errUnknownProfile
	}
	p.RemoveHosts(domains)
	if len(p.IPs) == 0 {
		hs.RemoveProfile(profile)
		if err := saveHosts(hs); err != nil {
			return err
		}
		okMsg(c, fmt.Sprintf("Profile '%s' removed.", profile))
		return nil
	}
	if err := saveHosts(hs); err != nil {
		return err
	}
	okMsg(c, fmt.Sprintf("Domains '%s' removed.", strings.Join(domains, ", ")))
	printQuiet(c, renderGroups(hs, []string{profile}))
	return nil
}

// ------------------------------------------------------------------ add

// fromFile parses a "from" file, returning a map of ip -> host names. The
// original tool keeps the hosts of every ip together and iterates the map, so
// the resulting order follows the Go map iteration order.
func parseFrom(path string) (map[string][]string, []string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, nil, err
	}
	defer f.Close()
	ips := map[string][]string{}
	var order []string
	sc := newScanner(f)
	for sc.Scan() {
		trim := strings.TrimSpace(sc.Text())
		if strings.HasPrefix(strings.ToLower(trim), "# end") {
			continue
		}
		if matchProfileHeader(trim) != nil {
			continue
		}
		body := trim
		if strings.HasPrefix(body, "#") {
			body = strings.TrimSpace(body[1:])
		}
		if i := strings.Index(body, "#"); i >= 0 {
			body = body[:i]
		}
		fields := strings.Fields(body)
		if len(fields) < 2 {
			continue
		}
		ip := net.ParseIP(fields[0])
		if ip == nil {
			continue
		}
		key := ip.String()
		if _, ok := ips[key]; !ok {
			order = append(order, key)
		}
		for _, h := range fields[1:] {
			ips[key] = append(ips[key], h)
		}
	}
	return ips, order, nil
}

func (h *HostsFile) mergeFrom(ips map[string][]string) {
	for key, hosts := range ips {
		ip := net.ParseIP(key)
		for _, host := range hosts {
			if p := h.current; p != nil {
				p.AddIP(ip, host)
			}
		}
	}
}

// ------------------------------------------------------------------ backup

func runBackup() func(*Command, []string) error {
	return func(c *Command, args []string) error {
		hs := c.hosts()
		path := flagStr(c, "path")
		name := filepath.Base(hostsFilePath(c)) + "." + time.Now().Format("20060102")
		dest := filepath.Join(path, name)
		data, err := os.ReadFile(hostsFilePath(c))
		if err != nil {
			return err
		}
		if err := os.WriteFile(dest, data, 0644); err != nil {
			return err
		}
		okMsg(c, fmt.Sprintf("Backup '%s' created.", dest))
		printQuiet(c, renderGroups(hs, allProfileNames(hs)))
		return nil
	}
}

// ------------------------------------------------------------------ restore

func runRestore() func(*Command, []string) error {
	return func(c *Command, args []string) error {
		from := flagStr(c, "from")
		data, err := os.ReadFile(from)
		if err != nil {
			return err
		}
		path := hostsFilePath(c)
		if err := os.WriteFile(path, data, 0644); err != nil {
			return err
		}
		restored, err := Parse(path)
		if err != nil {
			return err
		}
		okMsg(c, fmt.Sprintf("File '%s' restored.", from))
		printQuiet(c, renderGroups(restored, allProfileNames(restored)))
		return nil
	}
}
EOF
echo ok"}

