	sort.SliceStable(root.children, func(i, j int) bool {
		return root.children[i].Name() < root.children[j].Name()
	})

	return root
}

func runHelp(c *Command, args []string) error {
	root := c
	for root.parent != nil {
		root = root.parent
	}
	target, _, err := root.find(args)
	if err != nil || target == nil {
		out(fmt.Sprintf("Unknown help topic %#q\n", args))
		out(root.usageString())
		return nil
	}
	out(target.helpString())
	return nil
}

func main() {
	root := buildCommands()
	root.local.add(&Flag{Name: "help", Short: "h", Kind: "bool", NoOptDef: "true", Usage: "help for hostctl"})
	root.local.add(&Flag{Name: "version", Short: "v", Kind: "bool", NoOptDef: "true", Usage: "version for hostctl"})

	if _, err := root.execute(os.Args[1:]); err != nil {
		if err == errHelpRequested {
			return
		}
		errorMsg(err)
		os.Exit(1)
	}
}
EOF
echo ok"}

