package main

import (
	"fmt"
	"net"
	"os"
	"strings"
)

// parseFrom reads a "from" file and groups its rows by ip. The host names of a
// single ip stay together, the ips themselves are iterated in Go map order.
func parseFrom(path string) (map[string][]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	ips := map[string][]string{}
	sc := newScanner(f)
	for sc.Scan() {
		trim := strings.TrimSpace(sc.Text())
		if strings.HasPrefix(strings.ToLower(trim), "# end") {
			continue
		}
		if _, _, ok := matchProfileHeader(trim); ok {
			continue
		}
		body := trim
		if strings.HasPrefix(body, "#") {
			body = strings.TrimSpace(body[1:])
		}
		if i := strings.Index(body, "#"); i >= 0 {
			body = body[:i]
		}
		fields := strings.Fields(body)
		if len(fields) < 2 {
			continue
		}
		ip := net.ParseIP(fields[0])
		if ip == nil {
			continue
		}
		key := ip.String()
		ips[key] = append(ips[key], fields[1:]...)
	}
	return ips, nil
}

// mergeIPs adds the rows of the map to the profile. Existing ip groups are
// extended in place, new ones are appended at the end.
func (h *HostsFile) mergeIPs(p *Profile, ips map[string][]string) {
	for key, hosts := range ips {
		ip := net.ParseIP(key)
		for _, host := range hosts {
			p.AddIP(ip, host)
		}
	}
}

func runAdd(c *Command, args []string) error {
	hs := c.hosts()
	ips, err := parseFrom(flagStr(c, "from"))
	if err != nil {
		return err
	}
	p, ok := hs.Profile(args[0])
	if !ok {
		p = hs.AddProfile(args[0], true)
	}
	h.mergeIPs(p, ips)
	if err := hs.Save(); err != nil {
		return err
	}
	printResult(c, renderGroups(hs, []string{args[0]}))
	return waitAndReverse(c, args, "remove", func() error {
		return reverseRemove(c, args)
	})
}

func runAddDomains(c *Command, args []string) error {
	hs := c.hosts()
	ip := net.ParseIP(flagStr(c, "ip"))
	p, ok := hs.Profile(args[0])
	if !ok {
		p = hs.AddProfile(args[0], true)
	}
	for _, d := range args[1:] {
		p.AddIP(ip, d)
	}
	if err := hs.Save(); err != nil {
		return err
	}
	okMsg(c, fmt.Sprintf("Domains '%s' added.", strings.Join(args[1:], ", ")))
	printResult(c, renderGroups(hs, []string{args[0]}))
	return waitAndReverse(c, args, "remove domains", func() error {
		return reverseRemoveDomains(c, args)
	})
}

func runReplace(c *Command, args []string) error {
	hs := c.hosts()
	ips, err := parseFrom(flagStr(c, "from"))
	if err != nil {
		return err
	}
	hs.RemoveProfile(args[0])
	p := hs.AddProfile(args[0], true)
	h.mergeIPs(p, ips)
	if err := hs.Save(); err != nil {
		return err
	}
	printQuiet(c, renderGroups(hs, []string{args[0]}))
	return nil
}

func runRemoveDomains(c *Command, args []string) error {
	if err := doRemoveDomains(c, args); err != nil {
		return err
	}
	return nil
}

func reverseRemove(c *Command, args []string) error {
	hs := c.hosts()
	var names []string
	for _, a := range args {
		if hs.HasProfile(a) {
			hs.RemoveProfile(a)
			names = append(names, a)
		}
	}
	if err := hs.Save(); err != nil {
		return err
	}
	okMsg(c, fmt.Sprintf("Profile(s) '%s' removed.", strings.Join(names, ", ")))
	printResult(c, renderGroups(hs, names))
	return nil
}

func reverseRemoveDomains(c *Command, args []string) error {
	return doRemoveDomains(c, args)
}
