cat > sync.go <<'EOF'
package main

import (
	"fmt"
	"net"
	"path/filepath"
	"strings"
)

func runSyncDocker(c *Command, args []string) error {
	containers, err := dockerContainers(flagStr(c, "network"))
	if err != nil {
		return err
	}
	hs := c.hosts()
	domain := flagStr(c, "domain")
	if domain == "" {
		domain = "loc"
	}
	ips := map[string][]string{}
	for _, ct := range containers {
		addContainerRows(ips, ct, "", domain, nil)
	}
	hs.RemoveProfile(args[0])
	p := hs.AddProfile(args[0], true)
	h.mergeIPs(p, ips)
	if err := hs.Save(); err != nil {
		return err
	}
	printResult(c, renderGroups(hs, []string{args[0]}))
	return waitAndReverse(c, args, "remove", func() error {
		return reverseRemove(c, args)
	})
}

func runSyncCompose(c *Command, args []string) error {
	containers, err := dockerContainers(flagStr(c, "network"))
	if err != nil {
		return err
	}
	composeFile := flagStr(c, "compose-file")
	services, err := parseCompose(composeFile)
	if err != nil {
		return fmt.Errorf("error parsing docker-compose content: %v", err)
	}
	project := flagStr(c, "project-name")
	if project == "" {
		project = filepath.Base(filepath.Dir(composeFile))
	}
	hs := c.hosts()
	domain := flagStr(c, "domain")
	if domain == "" {
		domain = "loc"
	}
	prefix := project + "_"
	if flagBool(c, "prefix") {
		prefix = ""
	}
	ips := map[string][]string{}
	for _, ct := range containers {
		name := containerName(ct)
		if !strings.HasPrefix(name, project+"_") {
			continue
		}
		short := name[len(project)+1:]
		service := short
		if i := strings.LastIndex(short, "_"); i >= 0 {
			service = short[:i]
		}
		if !contains(services, service) {
			continue
		}
		addContainerRows(ips, ct, prefix+short, domain, nil)
	}
	hs.RemoveProfile(args[0])
	p := hs.AddProfile(args[0], true)
	h.mergeIPs(p, ips)
	if err := hs.Save(); err != nil {
		return err
	}
	printResult(c, renderGroups(hs, []string{}))
	return waitAndReverse(c, args, "remove", func() error {
		return reverseRemove(c, args)
	})
}

// addContainerRows collects one row per network of the container.
func addContainerRows(ips map[string][]string, ct *container, host, domain string, filter *netNetwork) {
	if host == "" {
		host = containerName(ct)
	}
	full := host + "." + domain
	for _, nw := range ct.Networks {
		if filter != nil && nw.NetworkID != filter.ID {
			continue
		}
		if nw.IPAddress == "" {
			continue
		}
		ip := net.ParseIP(nw.IPAddress)
		ips[ip.String()] = append(ips[ip.String()], full)
	}
}
