package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"
)

const dockerAPIVersion = "1.42"
const defaultDockerHost = "unix:///var/run/docker.sock"

type networkEntry struct {
	IPAddress string `json:"IPAddress"`
	NetworkID string `json:"NetworkID"`
}

type containerSettings struct {
	Networks map[string]networkEntry `json:"Networks"`
}

type container struct {
	Names           []string          `json:"Names"`
	NetworkSettings containerSettings `json:"NetworkSettings"`
}

type netNetwork struct {
	Name string `json:"Name"`
	ID   string `json:"Id"`
}

func containerName(c *container) string {
	// The original indexes the first name without any check: an empty name
	// list makes the tool panic with an index out of range error.
	return c.Names[0][1:]
}

// errConnectionFailed mirrors the error reported by the docker client when the
// daemon cannot be reached at all.
type errConnectionFailed struct{ Host string }

func (e errConnectionFailed) Error() string {
	if e.Host == "" {
		return "Cannot connect to the Docker daemon. Is the docker daemon running?"
	}
	return fmt.Sprintf("Cannot connect to the Docker daemon at %s. Is the docker daemon running?", e.Host)
}

type dockerHost struct {
	scheme   string
	proto    string
	addr     string
	basePath string
}

func parseDockerHost(host string) (*dockerHost, error) {
	parts := strings.SplitN(host, "://", 2)
	if len(parts) == 1 {
		return nil, errors.New("unable to parse docker host `" + host + "`")
	}
	proto, addr := parts[0], parts[1]
	basePath := ""
	if proto == "tcp" {
		parsed, err := url.Parse("tcp://" + addr)
		if err != nil {
			return nil, err
		}
		addr = parsed.Host
		basePath = parsed.Path
	}
	return &dockerHost{scheme: "http", proto: proto, addr: addr, basePath: basePath}, nil
}

func (d *dockerHost) transport() (*http.Transport, error) {
	tr := &http.Transport{}
	switch d.proto {
	case "unix":
		path := d.addr
		tr.DialContext = func(ctx context.Context, network, addr string) (net.Conn, error) {
			var dn net.Dialer
			return dn.DialContext(ctx, "unix", path)
		}
		return tr, nil
	case "npipe":
		return tr, errors.New("protocol not available")
	}
	tr.Proxy = http.ProxyFromEnvironment
	return tr, nil
}

func (d *dockerHost) url(path string, query string) string {
	u := url.URL{Scheme: d.scheme, Host: d.addr, Path: d.basePath + path}
	if query != "" {
		u.RawQuery = query
	}
	return u.String()
}

type dockerClient struct {
	host *dockerHost
	http *http.Client
}

func newDockerClient() (*dockerClient, error) {
	host := os.Getenv("DOCKER_HOST")
	if host == "" {
		host = defaultDockerHost
	}
	h, err := parseDockerHost(host)
	if err != nil {
		return nil, err
	}
	tr, err := h.transport()
	if err != nil {
		return nil, err
	}
	return &dockerClient{host: h, http: &http.Client{Transport: tr}}, nil
}

func (c *dockerClient) do(method, path, query string, out interface{}) error {
	u := c.host.url(path, query)
	req, err := http.NewRequest(method, u, nil)
	if err != nil {
		return err
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return wrapConnectError(err, os.Getenv("DOCKER_HOST"))
	}
	defer resp.Body.Close()
	if resp.StatusCode/100 != 2 {
		return fmt.Errorf("request returned %s", resp.Status)
	}
	if out == nil {
		return nil
	}
	return json.NewDecoder(resp.Body).Decode(out)
}

func wrapConnectError(err error, host string) error {
	if uErr, ok := err.(*url.Error); ok {
		if nErr, ok := uErr.Err.(*net.OpError); ok && os.IsPermission(nErr.Err) {
			return errors.Wrap(err, "permission denied while trying to connect to the Docker daemon socket at "+host)
		}
	}
	if ne, ok := err.(net.Error); ok {
		if ne.Timeout() {
			return errConnectionFailed{Host: host}
		}
		if strings.Contains(err.Error(), "connection refused") || strings.Contains(err.Error(), "dial unix") {
			return errConnectionFailed{Host: host}
		}
	}
	return errors.Wrap(err, "error during connect")
}

// dockerContainers lists the containers, optionally filtered by network name.
func dockerContainers(network string) ([]*container, error) {
	cli, err := newDockerClient()
	if err != nil {
		return nil, err
	}
	var networkID string
	if network != "" {
		var networks []*netNetwork
		if err := cli.do(http.MethodGet, "/v"+dockerAPIVersion+"/networks", "", &networks); err != nil {
			return nil, err
		}
		found := false
		for _, n := range networks {
			if n.Name == network {
				networkID = n.ID
				found = true
				break
			}
		}
		if !found {
			return nil, fmt.Errorf("unknown network ID: '%s'", network)
		}
	}
	filters := map[string]map[string]bool{"status": {"running": true}}
	if networkID != "" {
		filters["network"] = map[string]bool{networkID: true}
	}
	raw, err := json.Marshal(filters)
	if err != nil {
		return nil, err
	}
	query := url.Values{"filters": []string{string(raw)}}.Encode()
	var containers []*container
	if err := cli.do(http.MethodGet, "/v"+dockerAPIVersion+"/containers/json", query, &containers); err != nil {
		return nil, err
	}
	return containers, nil
}

var _ = time.Second
EOF
echo ok"}

