package main

// renderGroups builds the row groups for the given profile names. Each profile
// becomes one group; profiles without rows are skipped.
func renderGroups(hs *HostsFile, names []string) [][]Row {
	var groups [][]Row
	for _, name := range names {
		if name == "default" {
			var rows []Row
			for _, e := range hs.Default {
				if e.Kind != entryHost {
					continue
				}
				rows = append(rows, Row{Profile: "default", Status: "on", IP: e.IP.String(), Host: e.Host})
			}
			if len(rows) > 0 {
				groups = append(groups, rows)
			}
			continue
		}
		p, ok := hs.Profile(name)
		if !ok {
			continue
		}
		status := "on"
		if !p.Status {
			status = "off"
		}
		var rows []Row
		for _, g := range p.IPs {
			if g.IP == nil {
				continue
			}
			for _, h := range g.Hosts {
				rows = append(rows, Row{Profile: name, Status: status, IP: g.IP.String(), Host: h})
			}
		}
		if len(rows) > 0 {
			groups = append(groups, rows)
		}
	}
	return groups
}

func outputType(c *Command) string {
	o := "table"
	if f := c.flags().lookup("out"); f != nil && f.Str != "" {
		o = f.Str
	}
	if f := c.flags().lookup("raw"); f != nil && f.Bool {
		return "raw"
	}
	return o
}

func columnsFor(c *Command) []Column {
	if c.Name() == "status" {
		return statusColumns()
	}
	if f := c.flags().lookup("column"); f != nil && len(f.Strs) > 0 {
		return columnsFromNames(f.Strs)
	}
	return defaultColumns()
}
