package main

import (
	"fmt"
	"strings"
)

// waitAndReverse implements the --wait flag: it waits for the given duration
// (or until ctrl+c) and then runs the reverse action.
func waitAndReverse(c *Command, args []string, action string, reverse func() error) error {
	w := flagDur(c, "wait")
	if w < 0 {
		if !quiet(c) {
			out("\n")
		}
		return nil
	}
	if !quiet(c) {
		if w == 0 {
			fmt.Printf("[%s] Waiting until ctrl+c to %s from profile '%s'\n\n\n", colorize("1;36", symInfo), action, strings.Join(args, ", "))
		} else {
			fmt.Printf("[%s] Waiting for %s or ctrl+c to %s from profile '%s'\n\n\n", colorize("1;36", symInfo), w.String(), action, strings.Join(args, ", "))
		}
	}
	waitFor(w)
	out("\n")
	return reverse()
}
