package main

import (
	"fmt"
	"os"
)

// printList writes the report with fmt.Print. Read-only commands print their
// report even when --quiet is given.
func printList(c *Command, groups [][]Row) {
	printReport(c, groups, false, false)
}

// printResult writes the report with fmt.Println and honours the quiet flag.
func printResult(c *Command, groups [][]Row) {
	printReport(c, groups, true, true)
}

// printQuiet writes the report with fmt.Print and honours the quiet flag.
func printQuiet(c *Command, groups [][]Row) {
	printReport(c, groups, true, false)
}

func rowCount(groups [][]Row) int {
	n := 0
	for _, g := range groups {
		n += len(g)
	}
	return n
}

// printReport renders groups in the requested output format.
//
//	newline -> the report is written with fmt.Println (adds a blank line)
//	quiet   -> honour the --quiet flag
func printReport(c *Command, groups [][]Row, quietAware, newline bool) {
	if quietAware && quiet(c) {
		return
	}
	outType := outputType(c)
	if rowCount(groups) == 0 && outType != "json" {
		// an empty report renders to nothing
		if newline {
			out("\n")
		}
		return
	}
	columns := columnsFor(c)
	switch outType {
	case "json":
		out(RenderJSON(groups))
	case "raw":
		out(RenderRaw(columns, groups))
	case "markdown":
		out(RenderMarkdown(columns, groups))
	default:
		s := RenderTable(columns, groups)
		if newline {
			out(s + "\n")
		} else {
			out(s)
		}
	}
}

func infoMsg(c *Command, msg string) {
	if quiet(c) || outputType(c) == "json" {
		return
	}
	fmt.Printf("[%s] %s\n\n", colorize("1;36", symInfo), msg)
}

func okMsg(c *Command, msg string) {
	if quiet(c) {
		return
	}
	fmt.Printf("[%s] %s\n\n", colorize("1;32", symOK), msg)
}

func errorMsg(err error) {
	fmt.Printf("[%s] error: %s\n", colorize("1;31", symError), err)
}

func out(s string) { os.Stdout.WriteString(s) }
