{"command": "cat > /workspace/src/yaml.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"strings"
)

// yamlNode is a very small YAML document node: either a mapping, a sequence or
// a scalar. Only the subset needed by docker-compose files is supported.
type yamlNode struct {
	kind   int // 0 scalar, 1 mapping, 2 sequence
	scalar string
	keys   []string
	values map[string]*yamlNode
	items  []*yamlNode
}

func newYamlMapping() *yamlNode { return &yamlNode{kind: 1, values: map[string]*yamlNode{}} }

// parseComposeServices reads the service names of a compose file.
func parseComposeServices(content []byte) ([]string, error) {
	doc, err := parseYaml(content)
	if err != nil {
		return nil, err
	}
	if doc == nil || doc.kind != 1 {
		return nil, nil
	}
	svc, ok := doc.values["services"]
	if !ok || svc == nil {
		return nil, nil
	}
	if svc.kind == 1 {
		return svc.keys, nil
	}
	if svc.kind == 2 {
		var out []string
		for _, it := range svc.items {
			if it != nil && it.kind == 0 {
				out = append(out, it.scalar)
			}
		}
		return out, nil
	}
	return nil, nil
}

type yamlLine struct {
	indent  int
	text    string
	lineNum int
}

func parseYaml(content []byte) (*yamlNode, error) {
	var lines []yamlLine
	raw := strings.Split(string(content), "\n")
	for i, line := range raw {
		text := stripYamlComment(line)
		trimmed := strings.TrimSpace(text)
		if trimmed == "" || trimmed == "---" || trimmed == "..." {
			continue
		}
		indent := 0
		for indent < len(text) && text[indent] == ' ' {
			indent++
		}
		if indent < len(text) && text[indent] == '\t' {
			return nil, fmt.Errorf("yaml: line %d: found character that cannot start any token", i+1)
		}
		if trimmed[0] == '@' || trimmed[0] == '`' {
			return nil, errors.New("yaml: found character that cannot start any token")
		}
		lines = append(lines, yamlLine{indent: indent, text: strings.TrimRight(text[indent:], " \t"), lineNum: i + 1})
	}
	if len(lines) == 0 {
		return nil, nil
	}
	pos := 0
	node, err := parseBlock(lines, &pos, lines[0].indent)
	if err != nil {
		return nil, err
	}
	if pos != len(lines) {
		if node != nil && node.kind == 2 {
			return nil, fmt.Errorf("yaml: line %d: did not find expected '-' indicator", lines[0].lineNum)
		}
		return nil, fmt.Errorf("yaml: line %d: did not find expected key", lines[pos].lineNum)
	}
	return node, nil
}

func stripYamlComment(s string) string {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '#':
			if !inSingle && !inDouble && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t') {
				return s[:i]
			}
		}
	}
	return s
}

func parseBlock(lines []yamlLine, pos *int, indent int) (*yamlNode, error) {
	if *pos >= len(lines) {
		return nil, nil
	}
	if isSeqItem(lines[*pos].text) {
		return parseSequence(lines, pos, indent)
	}
	return parseMapping(lines, pos, indent)
}

func isSeqItem(t string) bool { return strings.HasPrefix(t, "- ") || t == "-" }

func parseMapping(lines []yamlLine, pos *int, indent int) (*yamlNode, error) {
	node := newYamlMapping()
	for *pos < len(lines) {
		line := lines[*pos]
		if line.indent < indent {
			break
		}
		if line.indent > indent {
			return nil, fmt.Errorf("yaml: line %d: mapping values are not allowed in this context", line.lineNum)
		}
		if isSeqItem(line.text) {
			return nil, fmt.Errorf("yaml: line %d: did not find expected '-' indicator", line.lineNum)
		}
		key, rest, err := splitYamlKey(line.text, line.lineNum)
		if err != nil {
			return nil, err
		}
		*pos++
		key = stripAnchor(key)
		if rest != "" {
			if isFlowOpen(rest) {
				return nil, fmt.Errorf("yaml: line %d: did not find expected ',' or '%s'", line.lineNum, flowClose(rest))
			}
			rest = stripAnchor(rest)
			if strings.HasPrefix(rest, "*") {
				if prev, ok := node.values[strings.TrimPrefix(rest, "*")]; ok && prev != nil {
					node.keys = append(node.keys, key)
					node.values[key] = prev
					continue
				}
				return nil, fmt.Errorf("yaml: unknown anchor '%s' referenced", strings.TrimPrefix(rest, "*"))
			}
			if rest == "|" || rest == ">" || rest == "|-" || rest == ">-" || rest == "|+" || rest == ">+" {
				// block scalar: consume the deeper indented lines
				var sb strings.Builder
				for *pos < len(lines) && lines[*pos].indent > indent {
					sb.WriteString(lines[*pos].text + "\n")
					*pos++
				}
				node.keys = append(node.keys, key)
				node.values[key] = &yamlNode{scalar: sb.String()}
				continue
			}
			node.keys = append(node.keys, key)
			node.values[key] = &yamlNode{scalar: unquoteYaml(rest)}
			continue
		}
		if *pos < len(lines) && lines[*pos].indent > indent {
			child, err := parseBlock(lines, pos, lines[*pos].indent)
			if err != nil {
				return nil, err
			}
			node.keys = append(node.keys, key)
			node.values[key] = child
			continue
		}
		node.keys = append(node.keys, key)
		node.values[key] = nil
	}
	return node, nil
}

func parseSequence(lines []yamlLine, pos *int, indent int) (*yamlNode, error) {
	node := &yamlNode{kind: 2}
	for *pos < len(lines) {
		line := lines[*pos]
		if line.indent != indent || !isSeqItem(line.text) {
			break
		}
		item := strings.TrimSpace(strings.TrimPrefix(line.text, "-"))
		*pos++
		item = stripAnchor(item)
		if item == "" {
			if *pos < len(lines) && lines[*pos].indent > indent {
				child, err := parseBlock(lines, pos, lines[*pos].indent)
				if err != nil {
					return nil, err
				}
				node.items = append(node.items, child)
				continue
			}
			node.items = append(node.items, nil)
			continue
		}
		if isFlowOpen(item) {
			return nil, fmt.Errorf("yaml: line %d: did not find expected ',' or '%s'", line.lineNum, flowClose(item))
		}
		if k, rest, err := splitYamlKey(item, line.lineNum); err == nil {
			m := newYamlMapping()
			m.keys = append(m.keys, stripAnchor(k))
			if rest != "" {
				m.values[stripAnchor(k)] = &yamlNode{scalar: unquoteYaml(rest)}
			}
			for *pos < len(lines) && lines[*pos].indent > indent {
				child, err := parseBlock(lines, pos, lines[*pos].indent)
				if err != nil {
					return nil, err
				}
				if child != nil && child.kind == 1 {
					for _, k := range child.keys {
						m.keys = append(m.keys, k)
						m.values[k] = child.values[k]
					}
				}
			}
			node.items = append(node.items, m)
			continue
		}
		node.items = append(node.items, &yamlNode{scalar: unquoteYaml(item)})
	}
	return node, nil
}

// stripAnchor removes the "&name" anchor prefix of a node.
func stripAnchor(s string) string {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "&") {
		if i := strings.IndexAny(s, " \t"); i >= 0 {
			return strings.TrimSpace(s[i+1:])
		}
		return ""
	}
	return s
}

// isFlowOpen reports whether s contains an unterminated flow collection.
func isFlowOpen(s string) bool {
	depth := 0
	open := byte(0)
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '[', '{':
			if depth == 0 {
				open = s[i]
			}
			depth++
		case ']', '}':
			depth--
		}
	}
	if depth > 0 {
		return true
	}
	return false
}

func flowClose(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] == '[' {
			return "]"
		}
		if s[i] == '{' {
			return "}"
		}
	}
	return "]"
}

func splitYamlKey(s string, lineNum int) (string, string, error) {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case ':':
			if inSingle || inDouble {
				continue
			}
			if i+1 < len(s) && s[i+1] != ' ' {
				continue
			}
			rest := strings.TrimSpace(s[i+1:])
			// "a: 1: 2" is invalid yaml
			if rest != "" && !isFlowOpen(rest) {
				if _, _, err := splitYamlKey(rest, lineNum); err == nil {
					return "", "", errors.New("yaml: mapping values are not allowed in this context")
				}
			}
			return unquoteYaml(s[:i]), rest, nil
		}
	}
	return "", "", errors.New("yaml: could not find expected ':'")
}

func unquoteYaml(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		return s[1 : len(s)-1]
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return s[1 : len(s)-1]
	}
	return s
}
