		p.i++
		for p.i < len(p.s) && p.s[p.i] != q {
			p.i++
		}
		if p.i < len(p.s) {
			p.i++
		}
		return &yamlNode{scalar: unquoteYaml(p.s[start:p.i])}, nil
	}
	for p.i < len(p.s) && p.s[p.i] != ',' && p.s[p.i] != '}' && p.s[p.i] != ']' && p.s[p.i] != ':' {
		p.i++
	}
	return &yamlNode{scalar: strings.TrimSpace(p.s[start:p.i])}, nil
}

func (p *flowParser) mapping() (*yamlNode, error) {
	p.i++ // consume '{'
	node := newYamlMapping()
	for {
		p.skipSpace()
		if p.i >= len(p.s) {
