// parseFlow parses a single line flow collection: {a: b, c: d} or [a, b].
func parseFlow(s string) (*yamlNode, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, nil
	}
	p := &flowParser{s: s}
	n, err := p.value()
	if err != nil {
		return nil, err
	}
	p.skipSpace()
	if p.i < len(p.s) {
		return nil, fmt.Errorf("yaml: did not find expected ',' or '%s'", p.s[len(p.s)-1:])
	}
	return n, nil
}

type flowParser struct {
	s string
	i int
}

func (p *flowParser) skipSpace() {
	for p.i < len(p.s) && (p.s[p.i] == ' ' || p.s[p.i] == '\t') {
		p.i++
	}
}

func (p *flowParser) value() (*yamlNode, error) {
	p.skipSpace()
	if p.i >= len(p.s) {
		return nil, nil
	}
	switch p.s[p.i] {
	case '{':
		return p.mapping()
	case '[':
		return p.sequence()
	}
	// scalar (possibly quoted)
	start := p.i
	if p.s[p.i] == '"' || p.s[p.i] == '\'' {
		q := p.s[p.i]
		p.i++
		for p.i < len(p.s) && p.s[p.i] != q {
			p.i++
		}
		if p.i < len(p.s) {
			p.i++
		}
		return &yamlNode{scalar: unquoteYaml(p.s[start:p.i])}, nil
	}
	for p.i < len(p.s) && p.s[p.i] != ',' && p.s[p.i] != '}' && p.s[p.i] != ']' && p.s[p.i] != ':' {
		p.i++
	}
	return &yamlNode{scalar: strings.TrimSpace(p.s[start:p.i])}, nil
}

func (p *flowParser) mapping() (*yamlNode, error) {
	p.i++ // consume '{'
	node := newYamlMapping()
	for {
		p.skipSpace()
		if p.i >= len(p.s) {
			return nil, errors.New("yaml: did not find expected ',' or '}'")
		}
		if p.s[p.i] == '}' {
			p.i++
			return node, nil
		}
		key, err := p.value()
		if err != nil {
			return nil, err
		}
		name := ""
		if key != nil {
			name = key.scalar
		}
		p.skipSpace()
		val := (*yamlNode)(nil)
		if p.i < len(p.s) && p.s[p.i] == ':' {
			p.i++
			val, err = p.value()
			if err != nil {
				return nil, err
			}
		}
		node.keys = append(node.keys, name)
		node.values[name] = val
		p.skipSpace()
		if p.i < len(p.s) && p.s[p.i] == ',' {
			p.i++
			continue
		}
	}
}

func (p *flowParser) sequence() (*yamlNode, error) {
	p.i++ // consume '['
	node := &yamlNode{kind: 2}
	for {
		p.skipSpace()
		if p.i >= len(p.s) {
			return nil, errors.New("yaml: did not find expected ',' or ']'")
		}
		if p.s[p.i] == ']' {
			p.i++
			return node, nil
		}
		v, err := p.value()
		if err != nil {
			return nil, err
		}
		node.items = append(node.items, v)
		p.skipSpace()
		if p.i < len(p.s) && p.s[p.i] == ',' {
			p.i++
			continue
		}
	}
}
