import sys; sys.path.insert(0,'/tmp/t')
exec(open('/tmp/t/sync_cases.py').read())
def yamls():
    return {
 'simple': "services:\n  web:\n    image: nginx\n", 'quoted': "services:\n  'web':\n    image: nginx\n  \"db\":\n    image: mysql\n",
 'comments': "# comment\nservices: # inline\n  web:\n    image: nginx # x\n# end\n", 'empty': "", 'noservices': "version: '3'\n",
 'servicesnull': "services:\n", 'seq': "services:\n  web:\n    image: nginx\n    ports:\n      - 80\n      - 443\n",
 'env': "services:\n  web:\n    environment:\n      A: 1\n      B: two\n", 'deep': "a:\n  b:\n    c:\n      d: 1\nservices:\n  web:\n    image: nginx\n",
 'multiline': "services:\n  web:\n    image: |\n      x\n      y\n", 'listsvc': "services:\n- web\n- db\n",
 'badindent': "services:\n  web:\n   image: nginx\n  db:\n    image: mysql\n", 'tabs': "services:\n\tweb:\n\t  image: nginx\n",
 'badflow': "not: [valid\n", 'svconly': "services: {web: {image: nginx}}\n", 'svconly2': "services:\n  web:\n  db:\n",
 'quotesv': 'services:\n  "my svc":\n    image: nginx\n', 'upperkeys': "Services:\n  web:\n    image: nginx\nservices:\n  api:\n    image: x\n",
 'anchors': "services:\n  web: &base\n    image: nginx\n  db: *base\n",
}
bad=0
for name, content in yamls().items():
    open('/tmp/t/_yc.yml','w').write(content)
    r1=run(ORIG,['sync','docker-compose','--compose-file','/tmp/t/_yc.yml','--project-name','p','pp'],'/tmp/t/src_plain')
    r2=run(MINE,['sync','docker-compose','--compose-file','/tmp/t/_yc.yml','--project-name','p','pp'],'/tmp/t/src_plain')
    def rows(o): return sorted(l for l in o.decode('utf8','replace').split('\n') if l.startswith('| '))
    def fl(f): return sorted(l for l in (f or b'').decode('utf8','replace').split('\n') if l and not l.startswith('#'))
    ok = r1[0]==r2[0] and rows(r1[1])==rows(r2[1]) and fl(r1[2])==fl(r2[2])
    if not ok:
        bad+=1; print("DIFF", name, r1[0], r2[0]); print("  o:", r1[1][:150]); print("  m:", r2[1][:150])
        if fl(r1[2])!=fl(r2[2]): print("  f1:", r1[2][-200:]); print("  f2:", r2[2][-200:])
print("BAD:", bad)
PY"}

